def find_fixed_point(F, bot, max_steps=1000):
    x = bot
    for k in range(max_steps):
        x_next = F(x)
        if x_next == x:
            return k, x
        x = x_next
    return None, x

def convergence_index(F, bot, le, target, max_steps=1000):
    x = bot
    for k in range(max_steps):
        if le(target, x):
            return k
        x = F(x)
    return None

def horn_clause_step(n, clauses, state):
    result = list(state)
    for clause in clauses:
        if all(state[p] for p in clause.premises):
            result[clause.conclusion] = True
    return tuple(result)
